const resp = (msg.payload && msg.payload.data) ? msg.payload.data : (msg.payload || {});
const rows = resp.rows || [];
const states = flow.get('states') || {};
const first = !flow.get('inited');
const out = [];
const now = Date.now();

for (const s of rows) {
    // 停用 / 从未上报的站点不监控，并清掉遗留状态
    if (s.status === 0 || !s.hasReported) {
        delete states[s.id];
        continue;
    }
    const prev = states[s.id];
    // 离线起点 ≈ 当前时间 - 后端算好的已离线秒数（恢复通知里算时长用）
    const offlineSince = s.isOnline ? null : now - (s.offlineSec || 0) * 1000;

    if (first) {
        // 首次轮询：只建基线，不通知，防部署/重启轰炸
        states[s.id] = { online: s.isOnline, offlineSince: offlineSince };
        continue;
    }
    if (!prev) {
        // 基线之后新出现的站点：已离线则直接告警，在线则只登记
        states[s.id] = { online: s.isOnline, offlineSince: offlineSince };
        if (!s.isOnline && (s.offlineSec || 0) >= 60) {
            out.push({ type: 'offline', site: s });
        }
        continue;
    }
    if (prev.online && !s.isOnline) {
        // 断线：只报一次；离线不足 60 秒先不报（防抖，下一轮再判）
        if ((s.offlineSec || 0) < 60) continue;
        states[s.id] = { online: false, offlineSince: offlineSince };
        out.push({ type: 'offline', site: s });
    } else if (!prev.online && s.isOnline) {
        // 恢复：补一条恢复通知，附本次离线时长
        const durationMin = prev.offlineSince ? Math.round((now - prev.offlineSince) / 60000) : null;
        states[s.id] = { online: true, offlineSince: null };
        out.push({ type: 'recovered', site: s, durationMin: durationMin });
    }
}

flow.set('inited', true);
flow.set('states', states);
msg.payload = out;
return msg;

const RECIPIENTS = 'user1@example.com,user2@example.com';  // ← 兜底收件人：站点没登记通知地址时发到这里，多个用英文逗号分隔

const s = msg.payload.site;
const type = msg.payload.type;
const where = [s.building, s.floor].filter(Boolean).join('');

// 通知地址复用采集点登记的 teams_webhook 字段：http(s) 开头是 Teams webhook（暂不支持，跳过），否则按邮箱用
const target = (s.notifyTarget || '').trim();
if (target && !/^https?:\/\//i.test(target)) {
    msg.to = target;
} else if (target) {
    // 登记的是 webhook 而本流只发邮件：退回兜底收件人，防止漏报
    msg.to = RECIPIENTS;
} else {
    msg.to = RECIPIENTS;
}
if (type === 'offline') {
    msg.topic = `【EdgeLink 断线告警】${s.siteName}`;
    msg.payload = [
        `采集点「${s.siteName}」${where ? '（' + where + '）' : ''}已断线。`,
        `最后心跳：${s.lastHeartbeat || '未知'}`,
        `已离线：${Math.floor((s.offlineSec || 0) / 60)} 分钟`,
        `负责人：${s.contact || '未登记'}`,
        '',
        '请检查该站点 Node-RED 运行状态与网络。'
    ].join('\n');
} else {
    msg.topic = `【EdgeLink 恢复通知】${s.siteName}`;
    msg.payload = [
        `采集点「${s.siteName}」${where ? '（' + where + '）' : ''}已恢复上线。`,
        msg.payload.durationMin != null ? `本次离线约 ${msg.payload.durationMin} 分钟。` : '',
        `负责人：${s.contact || '未登记'}`
    ].filter(Boolean).join('\n');
}
return msg;
